import {VEHICLES,PAINTS,WHEELS,INTERIORS,CITIES,LANGS,ROUTES,LOCALES} from './data.mjs?v=3';
import {translator} from './i18n.mjs?v=3';
import {vehicle,defaultConfig,configuration,money,number,recommend,encodeConfig,decodeConfig,loadState,validateGarage,planEnergy,haversine,fetchRoute,fetchWeather,routePath} from './core.mjs?v=3';
const root=document.getElementById('app');
let storage;try{storage=window.localStorage;}catch{storage={getItem(){throw Error('unavailable')},setItem(){throw Error('unavailable')}};}
let state=loadState(storage), t=translator(state.lang), menuOpen=false, compare=new Set(),filter='all',sort='design',cfg=decodeConfig(location.search);
let quiz={budget:90000,seats:5,priority:'distance'},quizResult=null,trip={from:'munich',to:'salzburg',model:'gt-01',start:90,reserve:15,price:.59},tripResult=null,tripBusy=false,tripFailed=false,weatherResult=null,weatherBusy=false,weatherFailed=false,controller=null,weatherController=null,toastTimer;
const path=location.pathname.endsWith('/')?location.pathname:location.pathname+'/';
const isHome=path==='/', isKnown=ROUTES.includes(path);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow='<span aria-hidden="true">↗</span>';
const a=(href,label,cls='')=>`<a class="${cls}" href="${esc(href)}">${esc(label)} ${arrow}</a>`;
const num=(n,d=0)=>number(n,state.lang,d),curr=c=>money(c,state.lang);
function img(v,cls='',filter='none'){return `<img class="car-image ${cls}" src="/assets/${v.image}" alt="${esc(v.name+' · '+t(v.kind))}" width="1600" height="1000" ${cls==='hero-car'?'fetchpriority="high"':'loading="lazy"'} style="filter:${filter}">`;}
function header(){const nav=[['/collection/','navCollection'],['/finder/','navFinder'],['/configure/','navConfig'],['/journey/','navJourney'],['/garage/','navGarage']];return `<a class="skip-link" href="#main">${t('skip')}</a><header class="site-header"><div class="header-inner"><button class="menu-toggle" type="button" data-action="menu" aria-expanded="${menuOpen}" aria-controls="main-nav" aria-label="${t(menuOpen?'close':'menu')}"><span></span><span></span></button><a href="/" class="wordmark" aria-label="Motion Atelier · ${esc(t('backHome'))}">MOTION ATELIER</a><button class="theme-toggle" type="button" data-action="theme" aria-label="${t(state.theme==='dark'?'themeLight':'themeDark')}" title="${t(state.theme==='dark'?'themeLight':'themeDark')}"><span aria-hidden="true">${state.theme==='dark'?'☀︎':'☾'}</span></button><label class="language"><span class="language-code" aria-hidden="true">${state.lang==='uk'?'UA':state.lang.toUpperCase()}<span>⌄</span></span><span class="sr-only">${t('language')}</span><select id="language" aria-label="${t('language')}">${[['de','DE · Deutsch'],['en','EN · English'],['ru','RU · Русский'],['uk','UA · Українська']].map(([k,v])=>`<option value="${k}" ${state.lang===k?'selected':''}>${v}</option>`).join('')}</select></label></div><nav id="main-nav" class="main-nav ${menuOpen?'open':''}" aria-label="${t('menu')}">${nav.map(([href,key])=>`<a href="${href}" ${path===href?'aria-current="page"':''}>${t(key)}${key==='navGarage'&&state.garage.length?` <span class="count">${state.garage.length}</span>`:''}</a>`).join('')}</nav></header>`;}
function footer(){return `<footer class="site-footer"><div class="footer-top"><a class="wordmark" href="/">MOTION ATELIER</a><p>${t('heroSub')}</p></div><div class="footer-bottom"><span>${t('demo')}</span><div>${a('/about/',t('navAbout'))}<a href="https://github.com/Netaniya/Netaniya/tree/main/portfolio/motion-atelier" target="_blank" rel="noopener noreferrer">GitHub ↗</a></div><span>© 2026 Natalie Ragulina (Netaniya)</span></div></footer>`;}
function specs(v){return `<dl class="specs"><div><dt>${t('range')}</dt><dd>${num(Math.floor(v.battery/v.consumption*100))}<small>${t('unitKm')}</small></dd></div><div><dt>${t('power')}</dt><dd>${num(v.power)}<small>${t('unitKw')}</small></dd></div><div><dt>${t('seats')}</dt><dd>${v.seats}</dd></div></dl>`;}
function vehicleCard(v,{selection=false,saved=null}={}){return `<article class="vehicle-card"><a class="vehicle-visual ${v.id}" href="/models/${v.id}/">${img(v)}<span class="visual-index">${v.id.slice(-2)}</span></a><div class="vehicle-heading"><div><p class="eyebrow">${t(v.kind)}</p><h3><a href="/models/${v.id}/">${v.name}</a></h3></div>${a('/configure/?model='+v.id,t('configure'),'text-link')}</div><p class="vehicle-story">${t(v.id==='gt-01'?'gtStory':v.id==='cross-02'?'crossStory':'sportStory')}</p>${specs(v)}<div class="vehicle-bottom"><span>${t('from')} <strong>${curr(v.price)}</strong></span>${selection?`<label class="compare-toggle"><input type="checkbox" name="compare" value="${v.id}" ${compare.has(v.id)?'checked':''}> ${t('compare')}</label>`:''}</div></article>`;}
function notice(){return `<p class="disclosure">${t('numbersNote')}</p>`;}
function pageHeading(eye,title,sub=''){return `<section class="page-heading wrap"><p class="eyebrow">${esc(eye)}</p><h1>${esc(title)}</h1>${sub?`<p class="lead">${esc(sub)}</p>`:''}</section>`;}
function home(){return `<section class="hero" aria-labelledby="hero-title"><div class="hero-scene" aria-hidden="true"></div><div class="hero-shade"></div><div class="hero-copy"><p class="eyebrow">${t('eyebrow')}</p><h1 id="hero-title"><span>${t('headline1')}</span><span>${t('headline2')}</span></h1><p>${t('heroSub')}</p><div class="button-row">${a('/collection/',t('discover'),'button primary')}${a('/configure/',t('configure'),'button glass')}</div></div><div class="hero-vehicle">${img(VEHICLES[0],'hero-car')}</div><div class="hero-bottom"><span>01 / GT 01</span><a href="#collection">${t('scroll')} ↓</a><span>${t('concept')}</span></div></section><section id="collection" class="section wrap"><div class="section-heading"><div><p class="eyebrow">MOTION COLLECTION</p><h2>${t('collectionTitle')}</h2></div>${a('/collection/',t('all'),'text-link')}</div><div class="vehicle-grid">${VEHICLES.map(v=>vehicleCard(v)).join('')}</div>${notice()}</section><section class="finder-feature"><div class="wrap feature-inner"><div><p class="eyebrow">${t('navFinder')}</p><h2>${t('homeFinderTitle')}</h2><p class="lead">${t('homeFinderBody')}</p>${a('/finder/',t('startFinder'),'button primary')}</div><div class="feature-car">${img(VEHICLES[1])}<span class="oversize-label" aria-hidden="true">02</span></div></div></section><section class="journey-feature wrap section"><div class="journey-photo" role="img" aria-label="${t('alpineScene')}"></div><div class="journey-copy"><p class="eyebrow">${t('navJourney')}</p><h2>${t('homeJourneyTitle')}</h2><p class="lead">${t('homeJourneyBody')}</p>${a('/journey/',t('planTrip'),'button dark')}</div></section><div class="wrap replay-row"><button class="text-button" data-action="replay">${t('replay')} ↺</button></div>`;}
function collection(){let list=VEHICLES.filter(v=>filter==='all'||v.kind===filter);if(sort==='price')list.sort((a,b)=>a.price-b.price);if(sort==='range')list.sort((a,b)=>b.battery/b.consumption-a.battery/a.consumption);const selected=VEHICLES.filter(v=>compare.has(v.id));return `${pageHeading(t('navCollection'),t('collectionTitle'),t('collectionSub'))}<section class="wrap section compact"><div class="collection-toolbar"><label>${t('filter')}<select id="vehicle-filter">${['all','grandTourer','crossover','sportCoupe'].map(k=>`<option value="${k}" ${filter===k?'selected':''}>${t(k)}</option>`).join('')}</select></label><label>${t('sort')}<select id="vehicle-sort">${[['design','sortDesign'],['price','sortPrice'],['range','sortRange']].map(([v,k])=>`<option value="${v}" ${sort===v?'selected':''}>${t(k)}</option>`).join('')}</select></label></div><div class="vehicle-grid">${list.map(v=>vehicleCard(v,{selection:true})).join('')||`<p>${t('emptyFilter')}</p>`}</div>${notice()}<section class="comparison"><h2>${t('comparison')}</h2>${selected.length<2?`<p>${t('compareHint')}</p>`:`<div class="table-scroll" tabindex="0" role="region" aria-label="${t('comparison')}"><table><thead><tr><th scope="col">${t('model')}</th>${selected.map(v=>`<th scope="col">${v.name}</th>`).join('')}</tr></thead><tbody>${[['range',v=>num(Math.floor(v.battery/v.consumption*100))+' '+t('unitKm')],['battery',v=>v.battery+' '+t('unitKwh')],['consumption',v=>num(v.consumption,1)+' '+t('unitKwh')+t('per100')],['power',v=>v.power+' '+t('unitKw')],['seats',v=>v.seats],['from',v=>curr(v.price)]].map(([k,fn])=>`<tr><th scope="row">${t(k)}</th>${selected.map(v=>`<td>${fn(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}</section></section>`;}
function modelPage(id){const v=VEHICLES.find(v=>v.id===id);if(!v)return notFound();return `<section class="model-hero ${v.id}"><div class="wrap"><p class="eyebrow">${t(v.kind)} · ${t('concept')}</p><h1>${v.name}</h1><p class="model-tagline">${t(v.id==='gt-01'?'gtStory':v.id==='cross-02'?'crossStory':'sportStory')}</p>${img(v,'model-car')}<div class="button-row">${a('/configure/?model='+v.id,t('configure'),'button primary')}${a('/journey/?model='+v.id,t('planTrip'),'button outline')}</div></div></section><section class="wrap section"><div class="model-spec-grid">${[['battery',v.battery+' '+t('unitKwh')],['power',v.power+' '+t('unitKw')],['range',num(Math.floor(v.battery/v.consumption*100))+' '+t('unitKm')],['consumption',num(v.consumption,1)+' '+t('unitKwh')+t('per100')],['seats',String(v.seats)],['acceleration',num(v.zero100,1)+' '+t('unitSeconds')]].map(([k,value])=>`<div><p>${t(k)}</p><strong>${value}</strong></div>`).join('')}</div>${notice()}<div class="editorial-band"><h2>${t('homeFinderTitle')}</h2>${a('/finder/',t('startFinder'),'button dark')}</div></section>`;}
function colourFilter(v,p){if(v.id==='gt-01')return p.filter;if(v.id==='cross-02')return {ocean:'sepia(1) saturate(3.2) hue-rotate(165deg) brightness(.8)',silver:'none',ruby:'sepia(1) saturate(3.2) hue-rotate(310deg) brightness(.75)',graphite:'saturate(.05) brightness(.55)'}[p.id];return {ocean:'hue-rotate(190deg) saturate(1.1)',silver:'saturate(.02) brightness(1.5)',ruby:'none',graphite:'saturate(.05) brightness(.55)'}[p.id];}
function configPage(){const v=vehicle(cfg.model),c=configuration(cfg),p=PAINTS.find(x=>x.id===cfg.paint);return `${pageHeading(t('navConfig'),t('configTitle'))}<section class="config-layout wrap"><div class="config-stage"><div class="stage-top"><span>${v.name}</span><span>${t('concept')}</span></div>${img(v,'config-car',colourFilter(v,p))}<p class="stage-caption">${t('colorNote')}</p><div class="config-stats"><span><strong>${num(c.range)}</strong> ${t('unitKm')}<small>${t('range')}</small></span><span><strong>${num(c.consumption,1)}</strong> ${t('unitKwh')}${t('per100')}<small>${t('consumption')}</small></span></div></div><form class="config-controls" id="config-form"><label class="field">${t('model')}<select name="model">${VEHICLES.map(x=>`<option value="${x.id}" ${x.id===cfg.model?'selected':''}>${x.name}</option>`).join('')}</select></label><fieldset><legend>${t('paint')} <span>${t(cfg.paint)}</span></legend><div class="paint-options">${PAINTS.map(p=>`<label class="paint-choice ${cfg.paint===p.id?'selected':''}" title="${t(p.id)}"><input type="radio" name="paint" value="${p.id}" ${cfg.paint===p.id?'checked':''}><span style="--paint:${p.color}"></span><span class="sr-only">${t(p.id)}</span></label>`).join('')}</div></fieldset>${optionGroup('wheels',WHEELS)}${optionGroup('interior',INTERIORS)}<p class="small muted">${t('wheelNote')}</p><div class="price-summary"><div><span>${t('base')}</span><span>${curr(v.price)}</span></div>${[PAINTS.find(x=>x.id===cfg.paint),WHEELS.find(x=>x.id===cfg.wheels),INTERIORS.find(x=>x.id===cfg.interior)].filter(x=>x.price).map(x=>`<div><span>${t(x.id)}</span><span>+ ${curr(x.price)}</span></div>`).join('')}<div class="total"><span>${t('total')}</span><strong>${curr(c.price)}</strong></div></div><button type="button" class="button primary full" data-action="save">${t('save')} ${arrow}</button><div class="config-actions"><button type="button" class="text-button" data-action="share">${t('share')} ↗</button><button type="button" class="text-button" data-action="download">${t('download')} ↓</button></div><p class="small muted">${t('garageLocal')}</p></form></section><div class="wrap">${notice()}</div>`;}
function optionGroup(key,values){return `<fieldset><legend>${t(key)}</legend><div class="option-list">${values.map(o=>`<label class="option-row"><input type="radio" name="${key}" value="${o.id}" ${cfg[key]===o.id?'checked':''}><span>${t(o.id)}</span><span>${o.price?'+ '+curr(o.price):t('included')}</span></label>`).join('')}</div></fieldset>`;}
function finder(){const list=quizResult||[];return `${pageHeading(t('navFinder'),t('finderTitle'),t('homeFinderBody'))}<section class="finder-layout wrap section compact"><form id="finder-form" class="panel"><label class="field">${t('budget')} · EUR<input type="number" name="budget" min="10000" max="200000" step="500" required value="${quiz.budget}"></label><label class="field">${t('requiredSeats')}<select name="seats">${[2,3,4,5].map(n=>`<option value="${n}" ${n===quiz.seats?'selected':''}>${n}</option>`).join('')}</select></label><fieldset><legend>${t('priority')}</legend>${['distance','family','performance'].map(k=>`<label class="option-row"><input type="radio" name="priority" value="${k}" ${quiz.priority===k?'checked':''}><span>${t(k)}</span></label>`).join('')}</fieldset><button class="button primary full" type="submit">${t('find')} ${arrow}</button><p class="small muted">${t('rulesNote')}</p></form><div id="finder-result" aria-live="polite">${list.length?`<p class="eyebrow">${t('recommendation')}</p>${list[0].eligible?'':`<p class="alert">${t('noMatch')}</p>`}${vehicleCard(list[0].v)}<div class="why"><h3>${t('why')}</h3><ul>${[[list[0].v.price<=quiz.budget*100,'fitsBudget'],[list[0].v.seats>=quiz.seats,'fitsSeats'],[list[0].v.tag===quiz.priority,'fitsPriority']].filter(([yes])=>yes).map(([,k])=>`<li>${t(k)}</li>`).join('')}</ul></div>`:`<div class="finder-placeholder">${img(VEHICLES[0])}<p>${t('homeFinderTitle')}</p></div>`}</div></section>`;}
function cityOptions(value){return CITIES.map(c=>`<option value="${c.id}" ${c.id===value?'selected':''}>${t(c.id)}</option>`).join('');}
function journey(){const v=vehicle(trip.model);return `${pageHeading(t('navJourney'),t('journeyTitle'))}<section class="journey-layout wrap section compact"><form id="trip-form" class="panel"><div class="field-pair"><label class="field">${t('origin')}<select name="from">${cityOptions(trip.from)}</select></label><label class="field">${t('destination')}<select name="to">${cityOptions(trip.to)}</select></label></div><label class="field">${t('model')}<select name="model">${VEHICLES.map(x=>`<option value="${x.id}" ${x.id===v.id?'selected':''}>${x.name}</option>`).join('')}</select></label><div class="field-pair"><label class="field">${t('startSoc')} · %<input type="number" name="start" min="20" max="100" required value="${trip.start}"></label><label class="field">${t('reserve')} · %<input type="number" name="reserve" min="5" max="40" required value="${trip.reserve}"></label></div><label class="field">${t('electricity')} · EUR/${t('unitKwh')}<input type="number" name="price" min="0" max="3" step=".01" required value="${trip.price}"></label><button type="submit" class="button primary full" ${tripBusy?'disabled':''}>${t(tripBusy?'loading':'calculate')} ${arrow}</button><p class="small muted">${t('externalNote')}</p></form><div id="trip-output" aria-live="polite">${tripFailed?`<div class="alert"><p>${t('routeFailure')}</p><button class="button outline" data-action="estimate">${t('estimate')}</button></div>`:''}${tripResult?renderTrip():`<div class="trip-placeholder"><span class="route-illustration" aria-hidden="true">↗</span><h2>${t('homeJourneyTitle')}</h2><p>${t('homeJourneyBody')}</p>${img(v)}</div>`}</div></section>`;}
function renderTrip(){const r=tripResult,from=CITIES.find(x=>x.id===trip.from),to=CITIES.find(x=>x.id===trip.to),d=routePath(r.geometry);return `<div class="route-result"><p class="eyebrow ${r.estimated?'estimated':''}">${t(r.estimated?'estimatedRoute':'liveRoute')}</p><h2>${t(trip.from)} <span class="muted">→</span> ${t(trip.to)}</h2><div class="route-canvas"><svg viewBox="0 0 900 440" role="img" aria-label="${t('routeDiagram')}"><defs><pattern id="grid" width="50" height="50" patternUnits="userSpaceOnUse"><path d="M 50 0 L 0 0 0 50" fill="none" stroke="#d7e6ed" stroke-width="1"/></pattern></defs><rect width="900" height="440" fill="url(#grid)"/><path class="route-shadow" d="${d}"/><path class="route-line ${r.estimated?'dashed':''}" d="${d}"/></svg><span class="map-north" aria-hidden="true">N ↑</span><p>${t('routeDiagram')} · © OpenStreetMap contributors</p></div><div class="trip-metrics">${[['distanceLabel',num(r.distance)+' '+t('unitKm')],['duration',num(Math.floor(Math.round(r.duration)/60))+' '+t('unitHours')+' '+num(Math.round(r.duration)%60)+' '+t('unitMinutes')],['energy',num(r.energy.required,1)+' '+t('unitKwh')],['stops',String(r.energy.stops)],['charging',num(r.energy.chargingMinutes)+' '+t('unitMinutes')],['energyCost',new Intl.NumberFormat(LOCALES[state.lang],{style:'currency',currency:'EUR'}).format(r.energy.cost)]].map(([k,v])=>`<div><span>${t(k)}</span><strong>${v}</strong></div>`).join('')}</div><p class="small muted">${t('chargingEnergy')}: ${num(r.energy.extra,1)} ${t('unitKwh')}</p><p class="disclosure">${t('tripNote')}</p><a class="text-link" href="https://www.openstreetmap.org/directions?engine=fossgis_osrm_car&route=${from.lat}%2C${from.lon}%3B${to.lat}%2C${to.lon}" target="_blank" rel="noopener noreferrer">${t('openMap')} ↗</a><section class="weather-box"><button class="button outline" data-action="weather" ${weatherBusy?'disabled':''}>${t(weatherBusy?'loading':'weather')}</button>${weatherFailed?`<p role="alert">${t('weatherFailure')}</p>`:''}${weatherResult?`<h3>${t('weatherTitle')}</h3><div class="weather-values"><span>${t('temperature')} <strong>${num(weatherResult.temperature,1)} °C</strong></span><span>${t('wind')} <strong>${num(weatherResult.wind,1)} ${t('unitSpeed')}</strong></span></div><p class="small muted">${t('asOf')}: ${esc(weatherResult.time.replace('T',' '))} · <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a> · CC BY 4.0</p>`:''}</section></div>`;}
function garage(){return `${pageHeading(t('navGarage'),t('garageTitle'),t('garageLocal'))}<section class="wrap section compact">${state.garage.length?`<div class="garage-grid">${state.garage.map(item=>{const c=configuration(item.config),v=vehicle(c.model),p=PAINTS.find(x=>x.id===c.paint);return `<article class="garage-item"><div class="vehicle-visual">${img(v,'',colourFilter(v,p))}</div><div class="garage-body"><h2>${v.name}</h2><p>${t(c.paint)} · ${t(c.wheels)} · ${t(c.interior)}</p><strong class="garage-price">${curr(c.price)}</strong><p class="small muted">${t('savedAt')} ${new Intl.DateTimeFormat(LOCALES[state.lang],{dateStyle:'medium'}).format(new Date(item.savedAt))}</p><div class="button-row">${a('/configure/?'+encodeConfig(c),t('edit'),'button outline')}<button class="text-button" data-action="remove" data-id="${esc(item.id)}">${t('remove')}</button></div></div></article>`;}).join('')}</div>`:`<div class="empty-garage">${img(VEHICLES[0])}<h2>${t('garageEmpty')}</h2>${a('/configure/',t('configure'),'button primary')}</div>`}</section>`;}
function about(){return `${pageHeading(t('navAbout'),t('aboutTitle'),t('aboutBody'))}<section class="about-layout wrap section compact"><div class="about-visual">${img(VEHICLES[0])}<span>MOTION / 2026</span></div><div class="about-text">${[['working','workingBody'],['limits','limitsBody'],['human','humanBody']].map(([h,b])=>`<section><h2>${t(h)}</h2><p>${t(b)}</p></section>`).join('')}<section><h2>${t('sources')}</h2><ul><li><a href="https://project-osrm.org/" target="_blank" rel="noopener noreferrer">OSRM</a> · <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">© OpenStreetMap contributors · ODbL</a></li><li><a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo · CC BY 4.0</a></li><li>${a('https://github.com/Netaniya/Netaniya/tree/main/portfolio/motion-atelier',t('viewCode'))}</li></ul></section></div></section>`;}
function notFound(){return `${pageHeading('404',t('notFound'))}<div class="wrap section">${a('/',t('backHome'),'button primary')}</div>`;}
function content(){if(isHome)return home();if(path==='/collection/')return collection();if(path==='/configure/')return configPage();if(path==='/finder/')return finder();if(path==='/journey/')return journey();if(path==='/garage/')return garage();if(path==='/about/')return about();if(path.startsWith('/models/'))return modelPage(path.split('/')[2]);return notFound();}
function render(focusName){t=translator(state.lang);document.documentElement.lang=state.lang;document.documentElement.dataset.theme=state.theme;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',state.theme==='dark'?'#101820':'#fbfcfc');root.innerHTML=header()+`<main id="main">${state.error?`<div class="storage-banner" role="status">${t('storageError')}</div>`:''}${content()}</main>`+footer();const titles={'/collection/':'navCollection','/configure/':'navConfig','/finder/':'navFinder','/journey/':'navJourney','/garage/':'navGarage','/about/':'navAbout'};document.title=(titles[path]?t(titles[path]):path.startsWith('/models/')?vehicle(path.split('/')[2]).name:'Motion Atelier')+' — Motion Atelier';if(focusName){const node=root.querySelector(focusName);if(node){if(!node.matches('a,button,input,select,textarea'))node.tabIndex=-1;node.focus();}}}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
function exportJson(data,filename){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),el=document.createElement('a');el.href=url;el.download=filename;el.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function freshGarage(){if(state.error)return state.garage;try{return validateGarage(storage.getItem('motion-garage'));}catch{state.error=true;return state.garage;}}
function persistGarage(items){state.garage=items;try{if(state.error)throw Error('blocked');storage.setItem('motion-garage',JSON.stringify(items));return true;}catch{state.error=true;return false;}}
function resetTrip(){controller?.abort();weatherController?.abort();controller=null;weatherController=null;tripResult=null;tripFailed=false;tripBusy=false;weatherResult=null;weatherFailed=false;weatherBusy=false;}
root.addEventListener('change',e=>{const el=e.target;if(el.id==='language'){state.lang=el.value;t=translator(state.lang);try{storage.setItem('motion-language',state.lang);}catch{state.error=true;}menuOpen=false;render('#language');return;}if(el.id==='vehicle-filter'){filter=el.value;render('#vehicle-filter');}if(el.id==='vehicle-sort'){sort=el.value;render('#vehicle-sort');}if(el.name==='compare'){if(el.checked)compare.add(el.value);else compare.delete(el.value);render(`input[name="compare"][value="${el.value}"]`);}if(el.closest('#config-form')){cfg={...cfg,[el.name]:el.value};history.replaceState(null,'','/configure/?'+encodeConfig(cfg));render(el.name==='model'?'#config-form [name="model"]':`[name="${el.name}"][value="${el.value}"]`);}if(el.closest('#trip-form')){trip={...trip,[el.name]:['start','reserve','price'].includes(el.name)?Number(el.value):el.value};resetTrip();render(`#trip-form [name="${el.name}"]`);}if(el.closest('#finder-form')){quiz={...quiz,[el.name]:['budget','seats'].includes(el.name)?Number(el.value):el.value};quizResult=null;document.getElementById('finder-result').innerHTML='';}});
root.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='finder-form'){const d=new FormData(e.target);quiz={budget:Number(d.get('budget')),seats:Number(d.get('seats')),priority:d.get('priority')};try{quizResult=recommend(quiz);render('#finder-result h3 a');}catch{toast(t('invalid'));}}if(e.target.id==='trip-form'){const d=new FormData(e.target);trip={from:d.get('from'),to:d.get('to'),model:d.get('model'),start:Number(d.get('start')),reserve:Number(d.get('reserve')),price:Number(d.get('price'))};await calculateTrip(false);}});
async function calculateTrip(estimate){resetTrip();if(trip.from===trip.to){toast(t('sameCity'));return;}const v=vehicle(trip.model),from=CITIES.find(x=>x.id===trip.from),to=CITIES.find(x=>x.id===trip.to);try{planEnergy({distance:0,battery:v.battery,consumption:v.consumption,start:trip.start,reserve:trip.reserve,price:trip.price,chargeKw:v.chargeKw});}catch{toast(t('invalid'));return;}tripBusy=true;render();const own=new AbortController();controller=own;const timer=setTimeout(()=>own.abort(),12000);try{const result=estimate?{distance:haversine(from,to)*1.25,duration:haversine(from,to)*1.25/80*60,geometry:[[from.lon,from.lat],[to.lon,to.lat]],estimated:true}:await fetchRoute(from,to,{signal:own.signal});if(controller!==own)return;tripResult={...result,energy:planEnergy({distance:result.distance,battery:v.battery,consumption:v.consumption,start:trip.start,reserve:trip.reserve,price:trip.price,chargeKw:v.chargeKw})};tripFailed=false;}catch{if(controller===own)tripFailed=true;}finally{clearTimeout(timer);if(controller===own){tripBusy=false;render();}}}
root.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const act=b.dataset.action;if(act==='theme'){state.theme=state.theme==='dark'?'light':'dark';try{storage.setItem('motion-theme',state.theme);}catch{}render('.theme-toggle');}if(act==='menu'){menuOpen=!menuOpen;render('.menu-toggle');}if(act==='replay')startIntro(true);if(act==='save'){const list=freshGarage();if(list.length>=30){toast(t('garageFull'));return;}const duplicate=list.some(x=>encodeConfig(x.config)===encodeConfig(cfg));if(!duplicate)persistGarage([...list,{id:crypto.randomUUID(),savedAt:new Date().toISOString(),config:{...cfg}}]);render();toast(t(state.error?'storageError':'saved'));}if(act==='share'){const url=new URL('/configure/?'+encodeConfig(cfg),location.origin).href;try{await navigator.clipboard.writeText(url);toast(t('copied'));}catch{const box=document.getElementById('share-fallback');box.replaceChildren();const label=document.createElement('label');label.textContent=t('copyManual');const input=document.createElement('input');input.readOnly=true;input.value=url;label.append(input);box.append(label);box.hidden=false;input.focus();input.select();}}if(act==='download'){exportJson({schema:'motion-atelier.configuration.v1',language:state.lang,fictional:true,config:cfg,calculation:configuration(cfg),exportedAt:new Date().toISOString()},'motion-atelier-'+cfg.model+'.json');}if(act==='remove'){if(!confirm(t('confirmRemove')))return;const list=freshGarage();persistGarage(list.filter(x=>x.id!==b.dataset.id));render();}if(act==='estimate')await calculateTrip(true);if(act==='weather'&&tripResult){weatherController?.abort();const own=new AbortController();weatherController=own;weatherBusy=true;weatherFailed=false;render();const timer=setTimeout(()=>own.abort(),10000);try{const w=await fetchWeather(CITIES.find(x=>x.id===trip.to),{signal:own.signal});if(weatherController===own)weatherResult=w;}catch{if(weatherController===own)weatherFailed=true;}finally{clearTimeout(timer);if(weatherController===own){weatherBusy=false;render();}}}});
window.addEventListener('storage',e=>{if(['motion-garage','motion-theme',null].includes(e.key)){const latest=loadState(storage);state.garage=latest.garage;state.error=latest.error;state.theme=latest.theme;render();}});
window.addEventListener('resize',()=>{if(!intro.hidden)finishIntro();});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){const overlay=document.getElementById('arrival');if(!overlay.hidden)finishIntro();else if(menuOpen){menuOpen=false;render('.menu-toggle');}}});
const intro=document.getElementById('arrival');let introTimer;function finishIntro(){clearTimeout(introTimer);intro.classList.add('departed');document.body.classList.remove('intro-playing');root.inert=false;intro.inert=true;const active=document.activeElement;if(intro.contains(active)){const main=document.getElementById('main');main.tabIndex=-1;main.focus({preventScroll:true});}setTimeout(()=>{intro.hidden=true;},700);try{sessionStorage.setItem('motion-arrival','seen');}catch{}}
function startIntro(force=false){if(!isHome)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let seen=false;try{seen=sessionStorage.getItem('motion-arrival')==='seen';}catch{}if(reduced||(!force&&seen)){intro.hidden=true;return;}clearTimeout(introTimer);intro.hidden=false;intro.inert=false;intro.classList.remove('departed','playing');intro.querySelector('[data-intro-label]').textContent=t('introText');intro.querySelector('[data-intro-skip]').textContent=t('skipIntro');intro.querySelector('img').alt='GT 01';if(force){const previous=document.documentElement.style.scrollBehavior;document.documentElement.style.scrollBehavior='auto';window.scrollTo(0,0);document.documentElement.style.scrollBehavior=previous;}const target=document.querySelector('.hero-vehicle').getBoundingClientRect(),moving=intro.querySelector('.arrival-vehicle');moving.style.top=target.top+'px';moving.style.width=target.width+'px';moving.style.height=target.height+'px';document.body.classList.add('intro-playing');root.inert=true;intro.querySelector('[data-intro-skip]').focus({preventScroll:true});requestAnimationFrame(()=>requestAnimationFrame(()=>intro.classList.add('playing')));introTimer=setTimeout(finishIntro,6500);}
intro.querySelector('[data-intro-skip]').addEventListener('click',finishIntro);intro.addEventListener('animationend',e=>{if(e.animationName==='arrivalDrive')intro.classList.add('arrived');});
const selectedModel=new URLSearchParams(location.search).get('model');if(path==='/journey/'&&VEHICLES.some(v=>v.id===selectedModel))trip.model=selectedModel;
render();if(isHome){let introReady=false;const asset=new Image();asset.onload=()=>{if(!introReady){introReady=true;startIntro();}};asset.onerror=()=>{introReady=true;intro.hidden=true;};asset.src='/assets/gt-blue-cinematic.webp';setTimeout(()=>{if(!asset.complete){introReady=true;intro.hidden=true;}},3000);}else intro.hidden=true;
